package pipeline

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"time"

	"github.com/holgeradam/kafka-testdata-generator/internal/generator"
)

// Outgoing is a fully-marshalled message ready for a sink: the raw Payload
// bytes plus the Key bytes (when the run configured a key) to associate with
// them. Sinks decode or forward these bytes as their transport requires.
type Outgoing struct {
	Key     []byte
	Payload []byte
}

// Sink is the destination seam for generated bytes. Adapters write to stdout
// (Dry run) or produce to Kafka. The Pipeline never knows which.
type Sink interface {
	Send(ctx context.Context, o Outgoing) error
	Close() error
}

// Config carries the fixed inputs of a run.
type Config struct {
	Generator *generator.Generator
	Schema    map[string]any
	Count     int
	RateLimit time.Duration
	KeyField  string
	// Warn, when non-nil, receives per-message stream diagnostics such as a
	// configured Key field that is missing from a generated Payload. Process
	// edge (main) passes stderr; tests pass a buffer.
	Warn io.Writer
}

// Stats reports the outcome of a run.
type Stats struct {
	Total   int64
	Acked   int64
	Failed  int64
	Elapsed time.Duration
}

// Pipeline drives a run: generate each Payload from the Message schema, extract
// the Key, marshal once, and hand bytes to the configured Sink until Count is
// reached or the context is cancelled.
type Pipeline struct {
	cfg  Config
	sink Sink
}

// New returns a Pipeline that sends generated payloads to the given sink.
func New(cfg Config, sink Sink) *Pipeline {
	return &Pipeline{cfg: cfg, sink: sink}
}

// Run executes the pipeline until Count payloads are handled or ctx is done.
func (p *Pipeline) Run(ctx context.Context) Stats {
	var total, acked, failed int64
	start := time.Now()

loop:
	for {
		if p.cfg.Count > 0 && total >= int64(p.cfg.Count) {
			break
		}

		select {
		case <-ctx.Done():
			break loop
		default:
		}

		payload := p.cfg.Generator.Value(p.cfg.Schema, "")
		total++

		var key []byte
		if p.cfg.KeyField != "" {
			key = marshalKey(payload, p.cfg.KeyField)
			if key == nil {
				p.warnf("Warning: field %q not found in payload, skipping\n", p.cfg.KeyField)
				failed++
				continue
			}
		}

		data, err := json.Marshal(payload)
		if err != nil {
			failed++
			continue
		}

		if err := p.sink.Send(ctx, Outgoing{Key: key, Payload: data}); err != nil {
			failed++
			continue
		}

		acked++
		// Rate limiting stays an inline sleep. A sleeper seam is deliberately
		// deferred until a second consumer of pacing exists (ADR-0004); revisit
		// only when pacing tests demand it.
		time.Sleep(p.cfg.RateLimit)
	}

	return Stats{Total: total, Acked: acked, Failed: failed, Elapsed: time.Since(start)}
}

// marshalKey extracts the value of keyField from the payload and returns its
// JSON bytes, or nil if the field is absent so the caller can count a failure.
func marshalKey(payload any, keyField string) []byte {
	m, ok := payload.(map[string]any)
	if !ok {
		return nil
	}
	v, ok := m[keyField]
	if !ok {
		return nil
	}
	b, err := json.Marshal(v)
	if err != nil {
		return nil
	}
	return b
}

func (p *Pipeline) warnf(format string, args ...any) {
	if p.cfg.Warn != nil {
		fmt.Fprintf(p.cfg.Warn, format, args...)
	}
}
